1	"use client";
2	
3	import { useEffect, useRef } from "react";
4	
5	/* Domains' own light field — same canvas technique every other account
6	 * page's aurora uses (sine-path ribbon strokes, additive blend, a blurred
7	 * halo plus a hard-edged core), its own ribbon family: blue into violet into
8	 * magenta, echoing the concept art's globe glow — a network/global-reach
9	 * palette, distinct from SSL's green "verified" one or Team's own mix.
10	 */
11	type Ribbon = {
12	  y: number; amp: number; freq: number; speed: number; phase: number;
13	  width: number; hue: [number, number]; alpha: number;
14	};
15	
16	const RIBBONS: Ribbon[] = [
17	  { y: 0.21, amp: 0.15, freq: 0.8,  speed: 0.12,  phase: 0.6, width: 58, hue: [206, 246], alpha: 0.19 },
18	  { y: 0.35, amp: 0.18, freq: 0.72, speed: -0.11, phase: 2.4, width: 68, hue: [246, 286], alpha: 0.16 },
19	  { y: 0.15, amp: 0.09, freq: 1.55, speed: 0.21,  phase: 4.0, width: 34, hue: [286, 318], alpha: 0.18 },
20	  { y: 0.29, amp: 0.06, freq: 2.3,  speed: 0.25,  phase: 5.6, width: 15, hue: [210, 232], alpha: 0.22 },
21	];
22	
23	export function DomainsAurora() {
24	  const ref = useRef<HTMLCanvasElement | null>(null);
25	
26	  useEffect(() => {
27	    const cv = ref.current;
28	    if (!cv) return;
29	    const ctx = cv.getContext("2d", { alpha: true });
30	    if (!ctx) return;
31	
32	    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
33	    let raf = 0, t = 0, running = true;
34	
35	    const fit = () => {
36	      const dpr = Math.min(2, window.devicePixelRatio || 1);
37	      const r = cv.getBoundingClientRect();
38	      cv.width = Math.max(1, Math.round(r.width * dpr));
39	      cv.height = Math.max(1, Math.round(r.height * dpr));
40	      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
41	    };
42	
43	    const strand = (r: Ribbon, w: number, h: number, time: number) => {
44	      const grad = ctx.createLinearGradient(0, 0, w, 0);
45	      grad.addColorStop(0, `hsla(${r.hue[0]},100%,62%,0)`);
46	      grad.addColorStop(0.35, `hsla(${r.hue[0]},100%,${r.alpha > 0.55 ? 78 : 64}%,${r.alpha})`);
47	      grad.addColorStop(0.65, `hsla(${r.hue[1]},100%,${r.alpha > 0.55 ? 80 : 66}%,${r.alpha})`);
48	      grad.addColorStop(1, `hsla(${r.hue[1]},100%,62%,0)`);
49	      ctx.strokeStyle = grad;
50	      ctx.lineWidth = r.width;
51	      ctx.lineCap = "round";
52	      ctx.beginPath();
53	      for (let x = 0; x <= w; x += 8) {
54	        const u = x / w;
55	        const y = h * (r.y
56	          + r.amp * Math.sin(u * Math.PI * 2 * r.freq + time * r.speed + r.phase)
57	          + r.amp * 0.4 * Math.sin(u * Math.PI * 2 * (r.freq * 1.7) - time * r.speed * 0.6));
58	        x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
59	      }
60	      ctx.stroke();
61	    };
62	
63	    const draw = () => {
64	      if (!running) return;
65	      const w = cv.clientWidth, h = cv.clientHeight;
66	      ctx.clearRect(0, 0, w, h);
67	      ctx.globalCompositeOperation = "lighter";
68	      ctx.filter = "blur(30px)";
69	      for (const r of RIBBONS) strand(r, w, h, t);
70	      ctx.filter = "blur(4px)";
71	      for (const r of RIBBONS) strand({ ...r, width: r.width * 0.22, alpha: r.alpha * 1.5 }, w, h, t);
72	      ctx.filter = "none";
73	      for (const r of RIBBONS) strand({ ...r, width: Math.max(1.2, r.width * 0.045), alpha: Math.min(1, r.alpha * 1.9) }, w, h, t);
74	      ctx.globalCompositeOperation = "source-over";
75	      t += 0.014;
76	      raf = requestAnimationFrame(draw);
77	    };
78	
79	    fit();
80	    if (reduced) {
81	      t = 2.4;
82	      const w = cv.clientWidth, h = cv.clientHeight;
83	      ctx.globalCompositeOperation = "lighter";
84	      ctx.filter = "blur(30px)";
85	      for (const r of RIBBONS) strand(r, w, h, t);
86	      ctx.filter = "none";
87	      for (const r of RIBBONS) strand({ ...r, width: Math.max(1.2, r.width * 0.045), alpha: Math.min(1, r.alpha * 1.9) }, w, h, t);
88	    } else {
89	      raf = requestAnimationFrame(draw);
90	    }
91	
92	    const onResize = () => fit();
93	    const onVis = () => {
94	      if (document.hidden) { running = false; cancelAnimationFrame(raf); }
95	      else if (!reduced && !running) { running = true; raf = requestAnimationFrame(draw); }
96	    };
97	    window.addEventListener("resize", onResize);
98	    document.addEventListener("visibilitychange", onVis);
99	    return () => {
100	      running = false;
101	      cancelAnimationFrame(raf);
102	      window.removeEventListener("resize", onResize);
103	      document.removeEventListener("visibilitychange", onVis);
104	    };
105	  }, []);
106	
107	  return (
108	    <div aria-hidden
109	         className="pointer-events-none fixed inset-x-0 top-0 z-0 h-[460px] overflow-hidden lg:left-[76px] xl:left-[248px]">
110	      {/* nx-mix-additive: this canvas paints with globalCompositeOperation
111	          "lighter", which only produces colour over a dark substrate — over a
112	          light page every stroke washes straight to a flat grey blob. Hidden
113	          in light mode by the same kill switch as StreamsBg/AuroraBg. */}
114	      <canvas ref={ref} className="nx-mix-additive h-full w-full opacity-80" />
115	      <span className="nx-aurora-dot" style={{ left: "15%", top: "17%", animationDelay: "0.5s" }} />
116	      <span className="nx-aurora-dot" style={{ left: "39%", top: "9%", animationDelay: "2.1s" }} />
117	      <span className="nx-aurora-dot" style={{ left: "61%", top: "23%", animationDelay: "3.3s" }} />
118	      <span className="nx-aurora-dot" style={{ left: "81%", top: "12%", animationDelay: "1.3s" }} />
119	      {/* Every stop mixes the theme's OWN background rather than a literal
120	          dark navy — see the identical fix on PlateBg's fade, same bug. */}
121	      <span className="absolute inset-0"
122	            style={{ background: "linear-gradient(180deg, color-mix(in srgb, var(--color-bg) 6%, transparent) 0%, color-mix(in srgb, var(--color-bg) 32%, transparent) 46%, color-mix(in srgb, var(--color-bg) 78%, transparent) 76%, var(--color-bg) 98%)" }} />
123	    </div>
124	  );
125	}
