1	"use client";
2	
3	import { useEffect, useRef } from "react";
4	
5	/* Page-level aurora.
6	 *
7	 * The reference screens carry a large, moving light field across the top-right
8	 * of every page — the earlier SVG ribbon was a 210px decoration inside one
9	 * header, which is why it read as absent. This is the real thing: layered
10	 * ribbons drifting on a canvas, capped at 30fps, paused when the tab is hidden
11	 * or the user asks for reduced motion.
12	 */
13	export function AuroraBg() {
14	  const ref = useRef<HTMLCanvasElement>(null);
15	
16	  useEffect(() => {
17	    const cv = ref.current;
18	    if (!cv) return;
19	    const g = cv.getContext("2d");
20	    if (!g) return;
21	
22	    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
23	    let raf = 0, last = 0, W = 0, H = 0;
24	    const dpr = Math.min(2, window.devicePixelRatio || 1);
25	
26	    const RIBBONS = [
27	      { y: 0.20, amp: 62, frq: 0.0016, spd: 0.16, th: 108, hue: 0.00, op: 0.15 },
28	      { y: 0.34, amp: 84, frq: 0.0012, spd: -0.11, th: 142, hue: 0.42, op: 0.11 },
29	      { y: 0.12, amp: 44, frq: 0.0023, spd: 0.24, th: 74,  hue: 0.72, op: 0.08 },
30	    ];
31	
32	    function size() {
33	      const r = cv!.getBoundingClientRect();
34	      W = Math.max(1, r.width); H = Math.max(1, r.height);
35	      cv!.width = Math.round(W * dpr); cv!.height = Math.round(H * dpr);
36	      g!.setTransform(dpr, 0, 0, dpr, 0, 0);
37	    }
38	
39	    function stop(x0: number, x1: number, hue: number, a: number) {
40	      const lg = g!.createLinearGradient(x0, 0, x1, 0);
41	      const A = ["#14c5e4", "#2f7eef", "#6f37d6", "#d623e1"];
42	      const i = Math.min(2, Math.floor(hue * 3));
43	      lg.addColorStop(0, "rgba(0,0,0,0)");
44	      lg.addColorStop(0.28, A[i] + Math.round(a * 190).toString(16).padStart(2, "0"));
45	      lg.addColorStop(0.62, A[i + 1] + Math.round(a * 255).toString(16).padStart(2, "0"));
46	      lg.addColorStop(1, "rgba(0,0,0,0)");
47	      return lg;
48	    }
49	
50	    function frame(now: number) {
51	      raf = requestAnimationFrame(frame);
52	      if (document.hidden) return;
53	      if (now - last < 1000 / 30) return;
54	      last = now;
55	      const t = now / 1000;
56	      g!.clearRect(0, 0, W, H);
57	      g!.globalCompositeOperation = "lighter";
58	      for (const r of RIBBONS) {
59	        g!.beginPath();
60	        for (let x = -40; x <= W + 40; x += 10) {
61	          const y = r.y * H
62	            + Math.sin(x * r.frq + t * r.spd) * r.amp
63	            + Math.sin(x * r.frq * 2.6 + t * r.spd * 1.7) * r.amp * 0.34;
64	          x === -40 ? g!.moveTo(x, y) : g!.lineTo(x, y);
65	        }
66	        g!.strokeStyle = stop(0, W, r.hue, r.op);
67	        g!.lineWidth = r.th;
68	        g!.lineCap = "round";
69	        g!.filter = "blur(30px)";
70	        g!.stroke();
71	        g!.filter = "blur(6px)";
72	        g!.lineWidth = r.th * 0.16;
73	        g!.strokeStyle = stop(0, W, r.hue, r.op * 0.9);
74	        g!.stroke();
75	        g!.filter = "none";
76	      }
77	      g!.globalCompositeOperation = "source-over";
78	    }
79	
80	    size();
81	    const ro = new ResizeObserver(size);
82	    ro.observe(cv);
83	    if (reduce) { frame(0); cancelAnimationFrame(raf); raf = 0; }
84	    else raf = requestAnimationFrame(frame);
85	    return () => { if (raf) cancelAnimationFrame(raf); ro.disconnect(); };
86	  }, []);
87	
88	  return (
89	    <div aria-hidden className="pointer-events-none fixed inset-x-0 top-0 z-0 h-[560px] overflow-hidden">
90	      <canvas ref={ref} className="nx-mix-additive h-full w-full opacity-70" />
91	      {/* fade it into the page so it never fights the cards */}
92	      <div className="absolute inset-0"
93	           style={{ background: "linear-gradient(180deg, transparent 30%, color-mix(in srgb, var(--color-bg) 68%, transparent) 70%, var(--color-bg) 100%)" }} />
94	    </div>
95	  );
96	}
