1	"use client";
2	
3	import { useEffect, useRef } from "react";
4	
5	/* Colliding ribbon streams.
6	 *
7	 * NOT the aurora. `AuroraBg` is a bundle of vertical silk strands pinched at a
8	 * waist and breathing in place; this is horizontal flow — several ribbons
9	 * travelling across the page on their own sine paths, crossing each other, and
10	 * flaring where they intersect. Each page in the account area gets its own
11	 * backdrop rather than one shared wash, which is what made six pages read as
12	 * one page repeated.
13	 *
14	 * Drawn on a canvas rather than with CSS because the interesting part is the
15	 * INTERSECTIONS: where two ribbons overlap the additive blend blooms, and that
16	 * cannot be expressed as a keyframe on an element.
17	 *
18	 * Honest about cost: this is a full-width canvas repainting every frame, so it
19	 * stops entirely when the tab is hidden, and it never starts at all for a
20	 * visitor who has asked for reduced motion — a moving backdrop is exactly what
21	 * that setting is about.
22	 */
23	
24	type Ribbon = {
25	  y: number; amp: number; freq: number; speed: number; phase: number;
26	  width: number; hue: [number, number]; alpha: number;
27	};
28	
29	export function StreamsBg({ className = "", seed = 0 }: { className?: string; seed?: number }) {
30	  const ref = useRef<HTMLCanvasElement | null>(null);
31	
32	  useEffect(() => {
33	    const cv = ref.current;
34	    if (!cv) return;
35	    const ctx = cv.getContext("2d", { alpha: true });
36	    if (!ctx) return;
37	
38	    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
39	    let raf = 0, t = 0, running = true;
40	
41	    /* Ribbons are seeded deterministically — a backdrop that reshuffles on
42	       every navigation reads as a glitch rather than a design.
43	
44	       `seed` picks a FLOW FAMILY, not a random shuffle. Each account page
45	       passes its own, so no two pages move the same way; the shapes below
46	       differ in structure (how many strands, how fast, how tightly they
47	       wind, where they cross), not just in phase. */
48	    /* Hues stay at 190+. Below that hsl turns green-cyan and then green, and
49	       there is no green anywhere in this brand — it was the one thing making
50	       the backdrop read as "off" no matter what the plates did. */
51	    const FAMILIES: Ribbon[][] = [
52	      /* 0 — wide, slow, few crossings. Reads as calm. (refer & earn) */
53	      [
54	        { y: 0.30, amp: 0.10, freq: 1.5, speed: 0.16, phase: 0.0, width: 46, hue: [190, 265], alpha: 0.17 },
55	        { y: 0.44, amp: 0.14, freq: 1.1, speed: -0.11, phase: 1.7, width: 62, hue: [265, 320], alpha: 0.14 },
56	        { y: 0.38, amp: 0.07, freq: 2.3, speed: 0.23, phase: 3.1, width: 30, hue: [192, 216], alpha: 0.19 },
57	        { y: 0.55, amp: 0.11, freq: 0.8, speed: -0.07, phase: 4.6, width: 78, hue: [220, 290], alpha: 0.10 },
58	      ],
59	      /* 1 — tight, fast, many crossings, low amplitude. Reads as busy. */
60	      [
61	        { y: 0.22, amp: 0.05, freq: 3.4, speed: 0.34, phase: 0.4, width: 22, hue: [192, 220], alpha: 0.20 },
62	        { y: 0.34, amp: 0.06, freq: 2.9, speed: -0.29, phase: 2.2, width: 28, hue: [255, 310], alpha: 0.17 },
63	        { y: 0.30, amp: 0.09, freq: 4.1, speed: 0.41, phase: 5.0, width: 16, hue: [193, 214], alpha: 0.22 },
64	        { y: 0.46, amp: 0.04, freq: 2.2, speed: -0.19, phase: 3.6, width: 36, hue: [230, 300], alpha: 0.13 },
65	        { y: 0.52, amp: 0.08, freq: 3.7, speed: 0.26, phase: 1.1, width: 20, hue: [200, 250], alpha: 0.15 },
66	      ],
67	      /* 2 — two heavy strands winding around one another, nothing else. */
68	      [
69	        { y: 0.36, amp: 0.19, freq: 0.7, speed: 0.09, phase: 0.0, width: 96, hue: [194, 232], alpha: 0.14 },
70	        { y: 0.36, amp: 0.19, freq: 0.7, speed: 0.09, phase: Math.PI, width: 96, hue: [278, 322], alpha: 0.14 },
71	        { y: 0.48, amp: 0.05, freq: 1.9, speed: -0.21, phase: 2.4, width: 18, hue: [200, 240], alpha: 0.19 },
72	      ],
73	      /* 3 — a single low sweep with fine filaments above it. */
74	      [
75	        { y: 0.58, amp: 0.16, freq: 0.6, speed: -0.06, phase: 1.2, width: 120, hue: [214, 268], alpha: 0.11 },
76	        { y: 0.24, amp: 0.03, freq: 5.2, speed: 0.44, phase: 0.7, width: 10, hue: [194, 212], alpha: 0.23 },
77	        { y: 0.28, amp: 0.04, freq: 4.4, speed: 0.37, phase: 3.9, width: 12, hue: [286, 326], alpha: 0.18 },
78	        { y: 0.19, amp: 0.02, freq: 6.1, speed: 0.52, phase: 5.5, width: 8,  hue: [196, 226], alpha: 0.20 },
