2	
3	import { useEffect, useRef } from "react";
4	
5	/* Flowing ribbon streams, for the base of a card.
6	 *
7	 * Not the page aurora reused at a smaller size: these are thin, discrete
8	 * strands with a visible edge that cross over one another, so the card reads as
9	 * having live throughput running under it rather than a colour wash.
10	 */
11	
12	const STRANDS = [
13	  { y: 0.56, amp: 0.16, frq: 1.7, spd: 0.22, w: 2.2, col: "56,200,235", a: 0.85 },
14	  { y: 0.62, amp: 0.21, frq: 1.3, spd: -0.17, w: 2.6, col: "150,90,240", a: 0.8 },
15	  { y: 0.70, amp: 0.14, frq: 2.2, spd: 0.29, w: 1.8, col: "225,80,215", a: 0.75 },
16	  { y: 0.76, amp: 0.10, frq: 2.8, spd: -0.24, w: 1.4, col: "60,150,255", a: 0.55 },
17	];
18	
19	export function Ribbons({ className = "" }: { className?: string }) {
20	  const ref = useRef<HTMLCanvasElement>(null);
21	
22	  useEffect(() => {
23	    const cv = ref.current; if (!cv) return;
24	    const g = cv.getContext("2d"); if (!g) return;
25	    const still = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
26	    const dpr = Math.min(2, window.devicePixelRatio || 1);
27	    let raf = 0, W = 0, H = 0, last = 0;
28	
29	    const size = () => {
30	      const r = cv.getBoundingClientRect();
31	      W = Math.max(1, r.width); H = Math.max(1, r.height);
32	      cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
33	      g.setTransform(dpr, 0, 0, dpr, 0, 0);
34	    };
35	
36	    const t0 = performance.now();
37	    function frame(now: number) {
38	      raf = requestAnimationFrame(frame);
39	      if (document.hidden) return;
40	      if (now - last < 1000 / 30) return;
41	      last = now;
42	      const t = still ? 0 : (now - t0) / 1000;
43	
44	      g!.clearRect(0, 0, W, H);
45	      g!.globalCompositeOperation = "lighter";
46	      g!.lineCap = "round";
47	
48	      for (const s of STRANDS) {
49	        /* each strand is drawn twice: a wide soft pass for the bloom and a
50	           tight bright pass for the edge that reads as the strand itself */
51	        for (const [mult, alpha, blur] of [[7, 0.16, 6], [1, 1, 0]] as const) {
52	          g!.beginPath();
53	          for (let x = -6; x <= W + 6; x += 6) {
54	            const u = x / W;
55	            const y = H * (s.y
56	              + s.amp * Math.sin(u * Math.PI * 2 * s.frq + t * s.spd * 3)
57	              + s.amp * 0.38 * Math.sin(u * Math.PI * 2 * s.frq * 2.3 - t * s.spd * 2.1));
58	            x === -6 ? g!.moveTo(x, y) : g!.lineTo(x, y);
59	          }
60	          const grad = g!.createLinearGradient(0, 0, W, 0);
61	          grad.addColorStop(0, `rgba(${s.col},0)`);
62	          grad.addColorStop(0.22, `rgba(${s.col},${s.a * alpha})`);
63	          grad.addColorStop(0.78, `rgba(${s.col},${s.a * alpha})`);
64	          grad.addColorStop(1, `rgba(${s.col},0)`);
65	          g!.strokeStyle = grad;
66	          g!.lineWidth = s.w * mult;
67	          g!.filter = blur ? `blur(${blur}px)` : "none";
68	          g!.stroke();
69	        }
70	      }
71	      g!.filter = "none";
72	      g!.globalCompositeOperation = "source-over";
73	    }
74	
75	    size();
76	    const ro = new ResizeObserver(size);
77	    ro.observe(cv);
78	    raf = requestAnimationFrame(frame);
79	    return () => { cancelAnimationFrame(raf); ro.disconnect(); };
80	  }, []);
81	
82	  return <canvas ref={ref} aria-hidden className={"block h-full w-full " + className} />;
83	}
