1	"use client";
2	
3	import { useEffect, useRef } from "react";
4	
5	/* The hero: a server rack with aurora light streams wrapping around it.
6	 *
7	 * Two things make this read like the concept. First, the streams are BUNDLES OF
8	 * THIN FILAMENTS, not broad bands — six or seven strands running roughly
9	 * parallel, each with a hairline core and a wide soft halo, fanning apart and
10	 * gathering along the path. A single wide band reads as a painted blade; a
11	 * bundle reads as light in motion.
12	 *
13	 * Second, the wrap needs two canvases with the rack between them and one shared
14	 * clock: a bundle dives behind the stack and the same bundle reappears on the
15	 * front layer lower down. A single layer, at any z-index, can only ever be in
16	 * front of the rack or behind it.
17	 */
18	
19	type Pt = [number, number];
20	type Stream = {
21	  p: [Pt, Pt, Pt, Pt];   // the bundle's centreline
22	  n: number;             // how many filaments
23	  spread: number;        // how far they fan apart, as a fraction of the box
24	  from: string; to: string;   // colour across the bundle, cyan -> magenta
25	  spd: number; amp: number;   // how the centreline breathes
26	  core: number; glow: number; // filament weight and halo weight
27	  body: number;               // the soft atmospheric stroke the threads sit in
28	  alpha: number;
29	};
30	
31	/* behind the rack: the long arc up the left and over the top */
32	const BACK: Stream[] = [
33	  { p: [[0.62, -0.02], [0.01, 0.06], [-0.06, 0.62], [0.22, 1.02]],
34	    n: 3, spread: 0.024, from: "80,232,252", to: "175,105,245",
35	    spd: 0.30, amp: 0.022, core: 1.6, glow: 15, body: 0.185, alpha: 1.05 },
36	  { p: [[0.92, -0.02], [0.58, 0.12], [0.42, 0.46], [0.46, 1.02]],
37	    n: 3, spread: 0.020, from: "165,110,250", to: "225,85,215",
38	    spd: -0.24, amp: 0.026, core: 1.0, glow: 11, body: 0.115, alpha: 0.55 },
39	];
40	
41	/* in front: the same light coming back out along the bottom right */
42	const FRONT: Stream[] = [
43	  { p: [[0.20, 0.70], [0.62, 0.96], [0.88, 0.60], [1.02, 0.86]],
44	    n: 3, spread: 0.022, from: "190,95,240", to: "80,222,252",
45	    spd: 0.34, amp: 0.024, core: 1.6, glow: 15, body: 0.170, alpha: 1.1 },
46	  { p: [[0.02, 1.02], [-0.03, 0.64], [0.16, 0.28], [0.56, -0.02]],
47	    n: 3, spread: 0.016, from: "90,238,255", to: "150,125,250",
48	    spd: -0.40, amp: 0.020, core: 1.0, glow: 9, body: 0.095, alpha: 0.6 },
49	];
50	
51	const bez = (a: number, b: number, c: number, d: number, t: number) => {
52	  const u = 1 - t;
53	  return u * u * u * a + 3 * u * u * t * b + 3 * u * t * t * c + t * t * t * d;
54	};
55	const mix = (a: string, b: string, t: number) => {
56	  const A = a.split(",").map(Number), B = b.split(",").map(Number);
57	  return A.map((v, i) => Math.round(v + (B[i] - v) * t)).join(",");
58	};
