60	function paint(g: CanvasRenderingContext2D, W: number, H: number, set: Stream[], t: number) {
61	  g.clearRect(0, 0, W, H);
62	  g.globalCompositeOperation = "lighter";
63	  g.lineCap = "round";
64	  g.lineJoin = "round";
65	  const N = 72;
66	  const S = Math.min(W, H);
67	
68	  for (let si = 0; si < set.length; si++) {
69	    const s = set[si];
70	    /* the inner control points drift, so the bundle breathes */
71	    const wob = (i: number, ax: number) =>
72	      s.amp * Math.sin(t * s.spd * 1.6 + i * 2.3 + ax * 1.1 + si * 1.7);
73	    const P: Pt[] = s.p.map((pt, i) =>
74	      i === 0 || i === 3 ? pt : [pt[0] + wob(i, 0), pt[1] + wob(i, 1)]);
75	
76	    const mid: Pt[] = [], nrm: Pt[] = [];
77	    for (let i = 0; i <= N; i++) {
78	      const u = i / N;
79	      mid.push([bez(P[0][0], P[1][0], P[2][0], P[3][0], u) * W,
80	                bez(P[0][1], P[1][1], P[2][1], P[3][1], u) * H]);
81	    }
82	    for (let i = 0; i <= N; i++) {
83	      const a = mid[Math.max(0, i - 1)], b = mid[Math.min(N, i + 1)];
84	      const dx = b[0] - a[0], dy = b[1] - a[1], L = Math.hypot(dx, dy) || 1;
85	      nrm.push([-dy / L, dx / L]);
86	    }
87	
88	    /* the soft body the threads live in */
89	    for (const [wm, am, bm] of [[1.40, 0.16, 0.26], [0.78, 0.30, 0.12], [0.34, 0.46, 0.04]] as const) {
90	      const bw = s.body * S * wm;
91	      const bg = g.createLinearGradient(mid[0][0], mid[0][1], mid[N][0], mid[N][1]);
92	      bg.addColorStop(0, `rgba(${s.from},0)`);
93	      bg.addColorStop(0.20, `rgba(${s.from},${s.alpha * am})`);
94	      bg.addColorStop(0.62, `rgba(${mix(s.from, s.to, 0.6)},${s.alpha * am})`);
95	      bg.addColorStop(1, `rgba(${s.to},0)`);
96	      g.beginPath();
97	      g.moveTo(mid[0][0], mid[0][1]);
98	      for (let i = 1; i <= N; i++) g.lineTo(mid[i][0], mid[i][1]);
99	      g.strokeStyle = bg;
100	      g.lineWidth = bw;
101	      g.filter = `blur(${Math.max(1, bw * bm).toFixed(1)}px)`;
102	      g.stroke();
103	    }
104	    g.filter = "none";
105	
106	    for (let k = 0; k < s.n; k++) {
107	      const q = s.n === 1 ? 0.5 : k / (s.n - 1);        // 0..1 across the bundle
108	      const col = mix(s.from, s.to, q);
109	      /* the bundle fans out through the middle of the run and gathers at both
110	         ends, and each filament has its own slow lateral drift */
111	      const path: Pt[] = [];
112	      for (let i = 0; i <= N; i++) {
113	        const u = i / N;
114	        const fan = Math.sin(Math.PI * u) ** 0.6;
115	        const drift = 0.30 * Math.sin(u * 5.5 + t * s.spd * 2.2 + k * 1.9);
116	        const off = (q - 0.5 + drift * 0.5) * s.spread * S * fan * 2;
117	        path.push([mid[i][0] + nrm[i][0] * off, mid[i][1] + nrm[i][1] * off]);
118	      }
119	
120	      /* halo first, then the hairline core on top of it */
121	      for (const [w, a, blur] of [
122	        [s.glow * 0.55, 0.13, s.glow * 0.5],
123	        [s.core, 0.9, 0],
124	      ] as const) {
125	        g.beginPath();
126	        g.moveTo(path[0][0], path[0][1]);
127	        for (let i = 1; i <= N; i++) g.lineTo(path[i][0], path[i][1]);
