154	export function RackHero({ className = "" }: { className?: string }) {
155	  const back = useRef<HTMLCanvasElement>(null);
156	  const front = useRef<HTMLCanvasElement>(null);
157	
158	  useEffect(() => {
159	    const b = back.current, f = front.current;
160	    if (!b || !f) return;
161	    const gb = b.getContext("2d"), gf = f.getContext("2d");
162	    if (!gb || !gf) return;
163	
164	    const still = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
165	    const dpr = Math.min(2, window.devicePixelRatio || 1);
166	    let raf = 0, W = 0, H = 0, last = 0;
167	
168	    const size = () => {
169	      const r = b.getBoundingClientRect();
170	      W = Math.max(1, r.width); H = Math.max(1, r.height);
171	      for (const [cv, g] of [[b, gb], [f, gf]] as const) {
172	        cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
173	        g.setTransform(dpr, 0, 0, dpr, 0, 0);
174	      }
175	    };
176	
177	    const t0 = performance.now();
178	    function frame(now: number) {
179	      raf = requestAnimationFrame(frame);
180	      if (document.hidden) return;
181	      if (now - last < 1000 / 30) return;
182	      last = now;
183	      const t = still ? 0 : (now - t0) / 1000;
184	      /* one clock for both layers, so a bundle that dives behind the rack and
185	         reappears in front stays in step */
186	      paint(gb!, W, H, BACK, t);
187	      paint(gf!, W, H, FRONT, t);
188	    }
189	
190	    size();
191	    const ro = new ResizeObserver(size);
192	    ro.observe(b);
193	    raf = requestAnimationFrame(frame);
194	    return () => { cancelAnimationFrame(raf); ro.disconnect(); };
195	  }, []);
196	
197	  return (
198	    <div className={"relative isolate " + (className.includes("h-[") ? "" : "aspect-[5/4] w-full ") + className}>
199	      {/* faded on every side, so the streams end in air rather than at a box
200	          edge — and so they cannot bleed under whatever sits next to them */}
201	      <canvas ref={back} aria-hidden className="z-0" style={FADE} />
202	      {/* the shadow it casts on nothing in particular, breathing with the rise */}
203	      <span aria-hidden
204	            className="nx-levitate-shadow absolute left-1/2 top-[80%] z-[5] h-[9%] w-[38%] -translate-x-1/2 rounded-[50%]"
205	            style={{ background: "radial-gradient(circle, rgba(2,6,20,0.9), rgba(2,6,20,0) 70%)" }} />
206	      <span className="pointer-events-none absolute left-1/2 top-1/2 z-10 h-[76%]
207	                       -translate-x-1/2 -translate-y-1/2">
208	        <img src="/nx/rack.webp" alt="" aria-hidden draggable={false}
209	             className="nx-levitate block h-full w-auto max-w-none select-none object-contain
210	                        drop-shadow-[0_26px_54px_rgba(0,4,20,0.8)]" />
211	      </span>
212	      <canvas ref={front} aria-hidden className="pointer-events-none z-20" style={FADE} />
213	    </div>
214	  );
215	}
