/* Shared theme-aware helpers for the account-page aurora canvases.
 *
 * Every ribbon backdrop in this family (StreamsBg, ActivityAurora,
 * BillingAurora, DomainsAurora, MailAurora, PartnerAurora, ServicesAurora,
 * SettingsAurora, SslAurora, SupportAurora, TeamAurora, ToolsAurora,
 * WhatsNewAurora) draws the same way: a linear-gradient stroke, three passes
 * (a blurred halo, a soft body, a hard core), composited with
 * `globalCompositeOperation = "lighter"` so overlapping ribbons bloom into
 * brighter light. That composite mode can only ever ADD light on top of
 * whatever is already there — over the near-black page these were designed
 * for that reads as glowing colour, but over a white/light page it
 * mathematically cannot produce colour: every stroke just pushes the pixels
 * under it toward white, which is the flat grey wash the user reported.
 *
 * The fix is not a different blend mode retune, it's a branch: dark keeps
 * "lighter" and every existing hsla lightness value untouched (so dark mode
 * is pixel-for-pixel the same as before this file existed); light switches
 * to normal "source-over" blending (so a stroke actually PAINTS colour onto
 * the page instead of only ever brightening it) and lowers each stop's
 * lightness by ~28 points — the same hue at ~35-50% L instead of ~62-80% L
 * reads as genuinely saturated colour against white rather than a near-white
 * tint — with alpha bumped up somewhat since normal blending does not stack
 * brightness across overlapping strokes the way additive does.
 *
 * Checked once per animation frame (`isLightTheme()` is a single attribute
 * read) rather than watched with a MutationObserver — these already run a
 * rAF loop, so the cost of checking is nothing next to the drawing itself,
 * and it means flipping the theme toggle repaints the very next frame.
 */

export function isLightTheme(): boolean {
  if (typeof document === "undefined") return false;
  return document.documentElement.getAttribute("data-theme") === "light";
}

/** Dark keeps the additive bloom; light needs real paint on the page. */
export function auroraComposite(isLight: boolean): GlobalCompositeOperation {
  return isLight ? "source-over" : "lighter";
}

/** Same ribbon shape both files' `strand()` functions already build a
 *  gradient from — {hue: [number, number], alpha: number}. */
type StrandLike = { hue: [number, number]; alpha: number };

/**
 * Builds the strand's linear gradient, branching lightness/alpha by theme.
 * Passing `isLight: false` reproduces the original expression exactly —
 * dark mode's output is unchanged.
 */
export function auroraStrandGradient(
  ctx: CanvasRenderingContext2D,
  r: StrandLike,
  w: number,
  isLight: boolean,
): CanvasGradient {
  const grad = ctx.createLinearGradient(0, 0, w, 0);
  const a = isLight ? Math.min(1, r.alpha * 1.7) : r.alpha;
  const endL = isLight ? 34 : 62;
  const midL0 = isLight ? (r.alpha > 0.55 ? 50 : 36) : (r.alpha > 0.55 ? 78 : 64);
  const midL1 = isLight ? (r.alpha > 0.55 ? 52 : 38) : (r.alpha > 0.55 ? 80 : 66);
  grad.addColorStop(0, `hsla(${r.hue[0]},100%,${endL}%,0)`);
  grad.addColorStop(0.35, `hsla(${r.hue[0]},100%,${midL0}%,${a})`);
  grad.addColorStop(0.65, `hsla(${r.hue[1]},100%,${midL1}%,${a})`);
  grad.addColorStop(1, `hsla(${r.hue[1]},100%,${endL}%,0)`);
  return grad;
}

