1	"use client";
2	
3	import { useEffect, useRef } from "react";
4	import { isLightTheme, auroraComposite, auroraStrandGradient } from "./auroraTheme";
5	
6	/* Domains' own light field — same canvas technique every other account
7	 * page's aurora uses (sine-path ribbon strokes, additive blend, a blurred
8	 * halo plus a hard-edged core), its own ribbon family: blue into violet into
9	 * magenta, echoing the concept art's globe glow — a network/global-reach
10	 * palette, distinct from SSL's green "verified" one or Team's own mix.
11	 */
12	type Ribbon = {
13	  y: number; amp: number; freq: number; speed: number; phase: number;
14	  width: number; hue: [number, number]; alpha: number;
15	};
16	
17	const RIBBONS: Ribbon[] = [
18	  { y: 0.21, amp: 0.15, freq: 0.8,  speed: 0.12,  phase: 0.6, width: 58, hue: [206, 246], alpha: 0.19 },
19	  { y: 0.35, amp: 0.18, freq: 0.72, speed: -0.11, phase: 2.4, width: 68, hue: [246, 286], alpha: 0.16 },
20	  { y: 0.15, amp: 0.09, freq: 1.55, speed: 0.21,  phase: 4.0, width: 34, hue: [286, 318], alpha: 0.18 },
21	  { y: 0.29, amp: 0.06, freq: 2.3,  speed: 0.25,  phase: 5.6, width: 15, hue: [210, 232], alpha: 0.22 },
22	];
23	
24	export function DomainsAurora() {
25	  const ref = useRef<HTMLCanvasElement | null>(null);
26	
27	  useEffect(() => {
28	    const cv = ref.current;
29	    if (!cv) return;
30	    const ctx = cv.getContext("2d", { alpha: true });
31	    if (!ctx) return;
32	
33	    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
34	    let raf = 0, t = 0, running = true;
35	
36	    const fit = () => {
37	      const dpr = Math.min(2, window.devicePixelRatio || 1);
38	      const r = cv.getBoundingClientRect();
39	      cv.width = Math.max(1, Math.round(r.width * dpr));
40	      cv.height = Math.max(1, Math.round(r.height * dpr));
41	      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
42	    };
43	
44	    const strand = (r: Ribbon, w: number, h: number, time: number, isLight: boolean) => {
45	      ctx.strokeStyle = auroraStrandGradient(ctx, r, w, isLight);
46	      ctx.lineWidth = r.width;
47	      ctx.lineCap = "round";
48	      ctx.beginPath();
49	      for (let x = 0; x <= w; x += 8) {
50	        const u = x / w;
51	        const y = h * (r.y
52	          + r.amp * Math.sin(u * Math.PI * 2 * r.freq + time * r.speed + r.phase)
53	          + r.amp * 0.4 * Math.sin(u * Math.PI * 2 * (r.freq * 1.7) - time * r.speed * 0.6));
54	        x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
55	      }
56	      ctx.stroke();
57	    };
58	
59	    const draw = () => {
60	      if (!running) return;
61	      const w = cv.clientWidth, h = cv.clientHeight;
62	      const isLight = isLightTheme();
63	      ctx.clearRect(0, 0, w, h);
64	      ctx.globalCompositeOperation = auroraComposite(isLight);
65	      ctx.filter = "blur(30px)";
66	      for (const r of RIBBONS) strand(r, w, h, t, isLight);
67	      ctx.filter = "blur(4px)";
68	      for (const r of RIBBONS) strand({ ...r, width: r.width * 0.22, alpha: r.alpha * 1.5 }, w, h, t, isLight);
69	      ctx.filter = "none";
70	      for (const r of RIBBONS) strand({ ...r, width: Math.max(1.2, r.width * 0.045), alpha: Math.min(1, r.alpha * 1.9) }, w, h, t, isLight);
71	      ctx.globalCompositeOperation = "source-over";
72	      t += 0.014;
73	      raf = requestAnimationFrame(draw);
74	    };
75	
76	    fit();
77	    if (reduced) {
78	      t = 2.4;
79	      const w = cv.clientWidth, h = cv.clientHeight;
80	      const isLight = isLightTheme();
81	      ctx.globalCompositeOperation = auroraComposite(isLight);
82	      ctx.filter = "blur(30px)";
83	      for (const r of RIBBONS) strand(r, w, h, t, isLight);
84	      ctx.filter = "none";
85	      for (const r of RIBBONS) strand({ ...r, width: Math.max(1.2, r.width * 0.045), alpha: Math.min(1, r.alpha * 1.9) }, w, h, t, isLight);
86	    } else {
87	      raf = requestAnimationFrame(draw);
88	    }
89	
90	    const onResize = () => fit();
91	    const onVis = () => {
92	      if (document.hidden) { running = false; cancelAnimationFrame(raf); }
93	      else if (!reduced && !running) { running = true; raf = requestAnimationFrame(draw); }
94	    };
95	    window.addEventListener("resize", onResize);
96	    document.addEventListener("visibilitychange", onVis);
97	    return () => {
98	      running = false;
99	      cancelAnimationFrame(raf);
100	      window.removeEventListener("resize", onResize);
101	      document.removeEventListener("visibilitychange", onVis);
102	    };
103	  }, []);
104	
105	  return (
106	    <div aria-hidden
107	         className="pointer-events-none fixed inset-x-0 top-0 z-0 h-[460px] overflow-hidden lg:left-[76px] xl:left-[248px]">
108	      {/* nx-mix-additive: this canvas paints with globalCompositeOperation
109	          "lighter", which only produces colour over a dark substrate — over a
110	          light page every stroke washes straight to a flat grey blob. Hidden
111	          in light mode by the same kill switch as StreamsBg/AuroraBg. */}
112	      <canvas ref={ref} className="nx-mix-additive h-full w-full opacity-80" />
113	      <span className="nx-aurora-dot" style={{ left: "15%", top: "17%", animationDelay: "0.5s" }} />
114	      <span className="nx-aurora-dot" style={{ left: "39%", top: "9%", animationDelay: "2.1s" }} />
115	      <span className="nx-aurora-dot" style={{ left: "61%", top: "23%", animationDelay: "3.3s" }} />
116	      <span className="nx-aurora-dot" style={{ left: "81%", top: "12%", animationDelay: "1.3s" }} />
117	      {/* Every stop mixes the theme's OWN background rather than a literal
118	          dark navy — see the identical fix on PlateBg's fade, same bug. */}
119	      <span className="absolute inset-0"
120	            style={{ background: "linear-gradient(180deg, color-mix(in srgb, var(--color-bg) 6%, transparent) 0%, color-mix(in srgb, var(--color-bg) 32%, transparent) 46%, color-mix(in srgb, var(--color-bg) 78%, transparent) 76%, var(--color-bg) 98%)" }} />
121	    </div>
122	  );
123	}
