1	"use client";
2	
3	import { useEffect, useRef } from "react";
4	import { isLightTheme, auroraComposite, auroraStrandGradient } from "./auroraTheme";
5	
6	/* Colliding ribbon streams.
7	 *
8	 * NOT the aurora. `AuroraBg` is a bundle of vertical silk strands pinched at a
9	 * waist and breathing in place; this is horizontal flow — several ribbons
10	 * travelling across the page on their own sine paths, crossing each other, and
11	 * flaring where they intersect. Each page in the account area gets its own
12	 * backdrop rather than one shared wash, which is what made six pages read as
13	 * one page repeated.
14	 *
15	 * Drawn on a canvas rather than with CSS because the interesting part is the
16	 * INTERSECTIONS: where two ribbons overlap the additive blend blooms, and that
17	 * cannot be expressed as a keyframe on an element.
18	 *
19	 * Honest about cost: this is a full-width canvas repainting every frame, so it
20	 * stops entirely when the tab is hidden, and it never starts at all for a
21	 * visitor who has asked for reduced motion — a moving backdrop is exactly what
22	 * that setting is about.
23	 */
24	
25	type Ribbon = {
26	  y: number; amp: number; freq: number; speed: number; phase: number;
27	  width: number; hue: [number, number]; alpha: number;
28	};
29	
30	export function StreamsBg({ className = "", seed = 0 }: { className?: string; seed?: number }) {
31	  const ref = useRef<HTMLCanvasElement | null>(null);
32	
33	  useEffect(() => {
34	    const cv = ref.current;
35	    if (!cv) return;
36	    const ctx = cv.getContext("2d", { alpha: true });
37	    if (!ctx) return;
38	
39	    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
40	    let raf = 0, t = 0, running = true;
41	
42	    /* Ribbons are seeded deterministically — a backdrop that reshuffles on
43	       every navigation reads as a glitch rather than a design.
44	
45	       `seed` picks a FLOW FAMILY, not a random shuffle. Each account page
46	       passes its own, so no two pages move the same way; the shapes below
47	       differ in structure (how many strands, how fast, how tightly they
48	       wind, where they cross), not just in phase. */
49	    /* Hues stay at 190+. Below that hsl turns green-cyan and then green, and
50	       there is no green anywhere in this brand — it was the one thing making
51	       the backdrop read as "off" no matter what the plates did. */
52	    const FAMILIES: Ribbon[][] = [
53	      /* 0 — wide, slow, few crossings. Reads as calm. (refer & earn) */
54	      [
55	        { y: 0.30, amp: 0.10, freq: 1.5, speed: 0.16, phase: 0.0, width: 46, hue: [190, 265], alpha: 0.17 },
56	        { y: 0.44, amp: 0.14, freq: 1.1, speed: -0.11, phase: 1.7, width: 62, hue: [265, 320], alpha: 0.14 },
57	        { y: 0.38, amp: 0.07, freq: 2.3, speed: 0.23, phase: 3.1, width: 30, hue: [192, 216], alpha: 0.19 },
58	        { y: 0.55, amp: 0.11, freq: 0.8, speed: -0.07, phase: 4.6, width: 78, hue: [220, 290], alpha: 0.10 },
59	      ],
60	      /* 1 — tight, fast, many crossings, low amplitude. Reads as busy. */
61	      [
62	        { y: 0.22, amp: 0.05, freq: 3.4, speed: 0.34, phase: 0.4, width: 22, hue: [192, 220], alpha: 0.20 },
63	        { y: 0.34, amp: 0.06, freq: 2.9, speed: -0.29, phase: 2.2, width: 28, hue: [255, 310], alpha: 0.17 },
64	        { y: 0.30, amp: 0.09, freq: 4.1, speed: 0.41, phase: 5.0, width: 16, hue: [193, 214], alpha: 0.22 },
65	        { y: 0.46, amp: 0.04, freq: 2.2, speed: -0.19, phase: 3.6, width: 36, hue: [230, 300], alpha: 0.13 },
66	        { y: 0.52, amp: 0.08, freq: 3.7, speed: 0.26, phase: 1.1, width: 20, hue: [200, 250], alpha: 0.15 },
67	      ],
68	      /* 2 — two heavy strands winding around one another, nothing else. */
69	      [
70	        { y: 0.36, amp: 0.19, freq: 0.7, speed: 0.09, phase: 0.0, width: 96, hue: [194, 232], alpha: 0.14 },
71	        { y: 0.36, amp: 0.19, freq: 0.7, speed: 0.09, phase: Math.PI, width: 96, hue: [278, 322], alpha: 0.14 },
72	        { y: 0.48, amp: 0.05, freq: 1.9, speed: -0.21, phase: 2.4, width: 18, hue: [200, 240], alpha: 0.19 },
73	      ],
74	      /* 3 — a single low sweep with fine filaments above it. */
