"use client";

import { useEffect, useRef } from "react";

/* Page-level aurora.
 *
 * The reference screens carry a large, moving light field across the top-right
 * of every page — the earlier SVG ribbon was a 210px decoration inside one
 * header, which is why it read as absent. This is the real thing: layered
 * ribbons drifting on a canvas, capped at 30fps, paused when the tab is hidden
 * or the user asks for reduced motion.
 */
export function AuroraBg() {

function stop(x0: number, x1: number, hue: number, a: number) {
  const lg = g!.createLinearGradient(x0, 0, x1, 0);
  const A = ["#14c5e4", "#2f7eef", "#6f37d6", "#d623e1"];
  const i = Math.min(2, Math.floor(hue * 3));
  lg.addColorStop(0, "rgba(0,0,0,0)");
  lg.addColorStop(0.28, A[i] + Math.round(a * 190).toString(16).padStart(2, "0"));
  lg.addColorStop(0.62, A[i + 1] + Math.round(a * 255).toString(16).padStart(2, "0"));
  lg.addColorStop(1, "rgba(0,0,0,0)");
  return lg;
}

function frame(now: number) {
  raf = requestAnimationFrame(frame);
  if (document.hidden) return;
  if (now - last < 1000 / 30) return;
  last = now;
  const t = now / 1000;
  g!.clearRect(0, 0, W, H);
  g!.globalCompositeOperation = "lighter";
  for (const r of RIBBONS) {
    g!.beginPath();
    for (let x = -40; x <= W + 40; x += 10) {
      const y = r.y * H
        + Math.sin(x * r.frq + t * r.spd) * r.amp
        + Math.sin(x * r.frq * 2.6 + t * r.spd * 1.7) * r.amp * 0.34;
      x === -40 ? g!.moveTo(x, y) : g!.lineTo(x, y);
    }
    g!.strokeStyle = stop(0, W, r.hue, r.op);
    g!.lineWidth = r.th;
    g!.lineCap = "round";
    g!.filter = "blur(30px)";
    g!.stroke();
    g!.filter = "blur(6px)";
    g!.lineWidth = r.th * 0.16;
    g!.strokeStyle = stop(0, W, r.hue, r.op * 0.9);
    g!.stroke();
    g!.filter = "none";
  }
  g!.globalCompositeOperation = "source-over";
}

