/* Dark: the original bright ramp, meant to bloom additively.
   Light: the same four hues pulled down to ~35-40% lightness (from a
   ~45-50% starting point — this ramp never sat as pale as the hsla
   aurora's 62-80%, so it needed a smaller drop) so they read as
   saturated colour once painted normally instead of only brightening. */
const RAMP_DARK = ["#14c5e4", "#2f7eef", "#6f37d6", "#d623e1"];
const RAMP_LIGHT = ["#0a7a91", "#1a4fb0", "#5220a0", "#a01aa8"];

function stop(x0: number, x1: number, hue: number, a: number, isLight: boolean) {
  const lg = g!.createLinearGradient(x0, 0, x1, 0);
  const A = isLight ? RAMP_LIGHT : RAMP_DARK;
  const i = Math.min(2, Math.floor(hue * 3));
  /* Normal blending does not stack brightness across overlapping
     strokes the way "lighter" does, so light mode gets more alpha. */
  const av = isLight ? Math.min(1, a * 2.2) : a;
  lg.addColorStop(0, "rgba(0,0,0,0)");
  lg.addColorStop(0.28, A[i] + Math.round(av * 190).toString(16).padStart(2, "0"));
  lg.addColorStop(0.62, A[i + 1] + Math.round(av * 255).toString(16).padStart(2, "0"));
  lg.addColorStop(1, "rgba(0,0,0,0)");
  return lg;
}

function frame(now: number) {
  raf = requestAnimationFrame(frame);
  if (document.hidden) return;
  if (now - last < 1000 / 30) return;
  last = now;
  const t = now / 1000;
  const isLight = isLightTheme();
  g!.clearRect(0, 0, W, H);
  g!.globalCompositeOperation = isLight ? "source-over" : "lighter";
  for (const r of RIBBONS) {
    g!.beginPath();
    for (let x = -40; x <= W + 40; x += 10) {
      const y = r.y * H
        + Math.sin(x * r.frq + t * r.spd) * r.amp
        + Math.sin(x * r.frq * 2.6 + t * r.spd * 1.7) * r.amp * 0.34;
      x === -40 ? g!.moveTo(x, y) : g!.lineTo(x, y);
    }
    g!.strokeStyle = stop(0, W, r.hue, r.op, isLight);
    g!.lineWidth = r.th;
    g!.lineCap = "round";
    g!.filter = "blur(30px)";
    g!.stroke();
    g!.filter = "blur(6px)";
    g!.lineWidth = r.th * 0.16;
    g!.strokeStyle = stop(0, W, r.hue, r.op * 0.9, isLight);
    g!.stroke();
    g!.filter = "none";
  }
  g!.globalCompositeOperation = "source-over";
}

